with enriched as (select *, row_number() over (partition by browser order by started_at, id) as seq_no, row_number() over (partition by customer_id order by started_at desc, id) as row_seq, row_number() over (partition by customer_id, device order by started_at desc, id) as event_seq from sessions) select id, customer_id, device, browser, started_at, row_seq, event_seq, case when device rlike '^(desktop|mobile)$' then 'GROUP_A' else 'GROUP_B' end as device_zone from enriched order by device_zone desc nulls first;
